  (4, 1, 4, '1:4', 'مَـٰلِكِ يَوْمِ ٱلدِّينِ', 'مَالِكِ يَوْمِ الدِّينِ', 'f19e0a517a68a043e08be6066abc107fff347f785c2ec1efe8b7364663923ee2', 1, 1, 1),
  (5, 1, 5, '1:5', 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', 'إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ', 'c44ba775d0ba7689a0d97e83a27cd9b5d917cb569f98013518018b591b42c015', 1, 1, 1),
