  (5863, 83, 15, '83:15', 'كَلَّآ إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍۢ لَّمَحْجُوبُونَ', 'كَلَّا إِنَّهُمْ عَن رَّبِّهِمْ يَوْمَئِذٍ لَّمَحْجُوبُونَ', 'ce268fe5c0d695cb8603e22a69452fee2d7cfabcec1b7d33879c625cb01ec5e8', 30, 59, 235),
  (5864, 83, 16, '83:16', 'ثُمَّ إِنَّهُمْ لَصَالُوا۟ ٱلْجَحِيمِ', 'ثُمَّ إِنَّهُمْ لَصَالُو الْجَحِيمِ', '2fd7f2630b1cd34277332a8eb25f9b84902a796ef4b641572d3059d69a393c9c', 30, 59, 235),
  (5865, 83, 17, '83:17', 'ثُمَّ يُقَالُ هَـٰذَا ٱلَّذِى كُنتُم بِهِۦ تُكَذِّبُونَ', 'ثُمَّ يُقَالُ هَٰذَا الَّذِي كُنتُم بِهِ تُكَذِّبُونَ', '4fcf6250321c304aad7e7bc17681606e9dfbcb814021463f734d5b9d569e5307', 30, 59, 235)
INSERT INTO ayahs (id, surah_id, verse_number, verse_key, text_uthmani, text_imlaei, text_uthmani_sha256, juz_number, hizb_number, rub_el_hizb_number) VALUES
  (5866, 83, 18, '83:18', 'كَلَّآ إِنَّ كِتَـٰبَ ٱلْأَبْرَارِ لَفِى عِلِّيِّينَ', 'كَلَّا إِنَّ كِتَابَ الْأَبْرَارِ لَفِي عِلِّيِّينَ', 'ddccb4cefa1041aec4b420c3561bb49fadf09270aae7493c162e19d6ffff7eec', 30, 59, 235),
  (5867, 83, 19, '83:19', 'وَمَآ أَدْرَىٰكَ مَا عِلِّيُّونَ', 'وَمَا أَدْرَاكَ مَا عِلِّيُّونَ', '21b798898251ea033a314322e7f5e2fa86825e3381bf6cfda78c29ca2ddda100', 30, 59, 235),
  (5868, 83, 20, '83:20', 'كِتَـٰبٌۭ مَّرْقُومٌۭ', 'كِتَابٌ مَّرْقُومٌ', '6d5184fa3a8545c5ad193d97198ae72aa3d43cadb67a8f3dff223fcd97efcc22', 30, 59, 235),
  (5869, 83, 21, '83:21', 'يَشْهَدُهُ ٱلْمُقَرَّبُونَ', 'يَشْهَدُهُ الْمُقَرَّبُونَ', '632fcf8120e910f4977e4ca0447b83783edd9c2a49f6af24bd6db266d8b098ae', 30, 59, 235),
  (5870, 83, 22, '83:22', 'إِنَّ ٱلْأَبْرَارَ لَفِى نَعِيمٍ', 'إِنَّ الْأَبْرَارَ لَفِي نَعِيمٍ', '86538137221e483f179a9f7fbf62fa85060be2b3ba66eeb4fbc414fcb411494a', 30, 59, 235),
  (5871, 83, 23, '83:23', 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'عَلَى الْأَرَائِكِ يَنظُرُونَ', 'd8c348079960c12009b7dbffcb4b40ea40097d9eb4d269e550043ec6cf948a56', 30, 59, 235),
  (5872, 83, 24, '83:24', 'تَعْرِفُ فِى وُجُوهِهِمْ نَضْرَةَ ٱلنَّعِيمِ', 'تَعْرِفُ فِي وُجُوهِهِمْ نَضْرَةَ النَّعِيمِ', '794ade70e38a22045dd81cb4754eec501f45ea0a31dd39bb71427ff12d64243d', 30, 59, 235),
  (5873, 83, 25, '83:25', 'يُسْقَوْنَ مِن رَّحِيقٍۢ مَّخْتُومٍ', 'يُسْقَوْنَ مِن رَّحِيقٍ مَّخْتُومٍ', 'a6b1c0a838d0179654346dab66058224450110ae2e8005363a9ec1ec1b560315', 30, 59, 235),
  (5874, 83, 26, '83:26', 'خِتَـٰمُهُۥ مِسْكٌۭ ۚ وَفِى ذَٰلِكَ فَلْيَتَنَافَسِ ٱلْمُتَنَـٰفِسُونَ', 'خِتَامُهُ مِسْكٌ ۚ وَفِي ذَٰلِكَ فَلْيَتَنَافَسِ الْمُتَنَافِسُونَ', '13a28ed5679ad305599aee88833b28a1ca97de567eb4146c97fec58ea03140e1', 30, 59, 235),
  (5875, 83, 27, '83:27', 'وَمِزَاجُهُۥ مِن تَسْنِيمٍ', 'وَمِزَاجُهُ مِن تَسْنِيمٍ', '371ab6a8dfe3646b45637d3cf387c9263e889bd1f9d6f048e88662d511e27d75', 30, 59, 235),
  (5876, 83, 28, '83:28', 'عَيْنًۭا يَشْرَبُ بِهَا ٱلْمُقَرَّبُونَ', 'عَيْنًا يَشْرَبُ بِهَا الْمُقَرَّبُونَ', '8818ba5d938b9ef3044acf32efb7056d23781bc8ae091fedd37793591d95be96', 30, 59, 235),
  (5877, 83, 29, '83:29', 'إِنَّ ٱلَّذِينَ أَجْرَمُوا۟ كَانُوا۟ مِنَ ٱلَّذِينَ ءَامَنُوا۟ يَضْحَكُونَ', 'إِنَّ الَّذِينَ أَجْرَمُوا كَانُوا مِنَ الَّذِينَ آمَنُوا يَضْحَكُونَ', 'd858e24cd754180fa6afe710046a9535c73afb0a5015ec64dfa7b1dc90d0f597', 30, 59, 235),
  (5878, 83, 30, '83:30', 'وَإِذَا مَرُّوا۟ بِهِمْ يَتَغَامَزُونَ', 'وَإِذَا مَرُّوا بِهِمْ يَتَغَامَزُونَ', '573f6bcf5892f72cd7e940f8e34c7162c0063e0c18a1fa4be5467252d25f13b7', 30, 59, 235),
  (5879, 83, 31, '83:31', 'وَإِذَا ٱنقَلَبُوٓا۟ إِلَىٰٓ أَهْلِهِمُ ٱنقَلَبُوا۟ فَكِهِينَ', 'وَإِذَا انقَلَبُوا إِلَىٰ أَهْلِهِمُ انقَلَبُوا فَكِهِينَ', 'dc67f4eb9f5a52507280522be03c3f6285f42e2617b2ea11056b976f2b256cb2', 30, 59, 235),
  (5880, 83, 32, '83:32', 'وَإِذَا رَأَوْهُمْ قَالُوٓا۟ إِنَّ هَـٰٓؤُلَآءِ لَضَآلُّونَ', 'وَإِذَا رَأَوْهُمْ قَالُوا إِنَّ هَٰؤُلَاءِ لَضَالُّونَ', 'ac70d32e529ca96d0e7832faeeb66ceae972df0795b29558a1eec1203862dfe9', 30, 59, 235),
  (5881, 83, 33, '83:33', 'وَمَآ أُرْسِلُوا۟ عَلَيْهِمْ حَـٰفِظِينَ', 'وَمَا أُرْسِلُوا عَلَيْهِمْ حَافِظِينَ', '873755af771f817c28ed98c9e87f1b154895493d808434e30dfee4cc9e8ba390', 30, 59, 235),
  (5882, 83, 34, '83:34', 'فَٱلْيَوْمَ ٱلَّذِينَ ءَامَنُوا۟ مِنَ ٱلْكُفَّارِ يَضْحَكُونَ', 'فَالْيَوْمَ الَّذِينَ آمَنُوا مِنَ الْكُفَّارِ يَضْحَكُونَ', '90e4536fc1c08acfc168aef52d48a2405e99a5b592fe3339e6df96385fa94161', 30, 59, 235),
  (5883, 83, 35, '83:35', 'عَلَى ٱلْأَرَآئِكِ يَنظُرُونَ', 'عَلَى الْأَرَائِكِ يَنظُرُونَ', 'd8c348079960c12009b7dbffcb4b40ea40097d9eb4d269e550043ec6cf948a56', 30, 59, 235),
  (5884, 83, 36, '83:36', 'هَلْ ثُوِّبَ ٱلْكُفَّارُ مَا كَانُوا۟ يَفْعَلُونَ', 'هَلْ ثُوِّبَ الْكُفَّارُ مَا كَانُوا يَفْعَلُونَ', '06ff7b4b6cd6b75ad8a2bea03d47a656ed01e202afc32e9f75ea356a0c7465da', 30, 59, 235),
  (5885, 84, 1, '84:1', 'إِذَا ٱلسَّمَآءُ ٱنشَقَّتْ', 'إِذَا السَّمَاءُ انشَقَّتْ', 'cc99f36d57fe763c80319bf2984a01d00ae59a041767db24cf87046e373f75cb', 30, 59, 236),
  (5886, 84, 2, '84:2', 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', '8355458e84437752ee84567d5713048e42289b6e83f65dc1da7fd4973d09308a', 30, 59, 236),
  (5887, 84, 3, '84:3', 'وَإِذَا ٱلْأَرْضُ مُدَّتْ', 'وَإِذَا الْأَرْضُ مُدَّتْ', '69afd00fbffee6ed5b95a1a7463d152372c7f4b92ffe0ee3533343bb2f9ad725', 30, 59, 236),
  (5888, 84, 4, '84:4', 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', 'وَأَلْقَتْ مَا فِيهَا وَتَخَلَّتْ', '3fbceeb879ee88e2436f3d4db9c34a6781e2c0ba9f685f19499dd0f0fb97b44b', 30, 59, 236),
  (5889, 84, 5, '84:5', 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', 'وَأَذِنَتْ لِرَبِّهَا وَحُقَّتْ', '8355458e84437752ee84567d5713048e42289b6e83f65dc1da7fd4973d09308a', 30, 59, 236),
  (5890, 84, 6, '84:6', 'يَـٰٓأَيُّهَا ٱلْإِنسَـٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًۭا فَمُلَـٰقِيهِ', 'يَا أَيُّهَا الْإِنسَانُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدْحًا فَمُلَاقِيهِ', 'e3ea3dbc72bd1f517afbfc38d3faf5ec11f3325d8ea3ca8658ac74dc4115fb5d', 30, 59, 236),
  (5891, 84, 7, '84:7', 'فَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ بِيَمِينِهِۦ', 'فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ', 'd90adbc2a24f611d79def1087be3f3a41b95f88ae65c65f5e8dd469973eacc24', 30, 59, 236),
  (5892, 84, 8, '84:8', 'فَسَوْفَ يُحَاسَبُ حِسَابًۭا يَسِيرًۭا', 'فَسَوْفَ يُحَاسَبُ حِسَابًا يَسِيرًا', '2f9c4ca794e73032516bffeea3b25347f4bba4e0b08875fbadd9f082345a0a67', 30, 59, 236),
  (5893, 84, 9, '84:9', 'وَيَنقَلِبُ إِلَىٰٓ أَهْلِهِۦ مَسْرُورًۭا', 'وَيَنقَلِبُ إِلَىٰ أَهْلِهِ مَسْرُورًا', 'f32758b6bd43bb78e81046cda2196be664ec12f19de03ded316fc0e9d60d900b', 30, 59, 236),
  (5894, 84, 10, '84:10', 'وَأَمَّا مَنْ أُوتِىَ كِتَـٰبَهُۥ وَرَآءَ ظَهْرِهِۦ', 'وَأَمَّا مَنْ أُوتِيَ كِتَابَهُ وَرَاءَ ظَهْرِهِ', '7aca36dfa27e71c6336b57a137fe59221a7cfe58dca1ada4e0a49d26f4cd7515', 30, 59, 236),
  (5895, 84, 11, '84:11', 'فَسَوْفَ يَدْعُوا۟ ثُبُورًۭا', 'فَسَوْفَ يَدْعُو ثُبُورًا', '134572d21ab7588073dcebc90afb273951eb2edea397f7dd7aabd152ed603f59', 30, 59, 236),
  (5896, 84, 12, '84:12', 'وَيَصْلَىٰ سَعِيرًا', 'وَيَصْلَىٰ سَعِيرًا', '6862c10b2f1b1e481e87942b95e15f307bfd8ed7de354ddf0a31a97ee96777c8', 30, 59, 236),
  (5897, 84, 13, '84:13', 'إِنَّهُۥ كَانَ فِىٓ أَهْلِهِۦ مَسْرُورًا', 'إِنَّهُ كَانَ فِي أَهْلِهِ مَسْرُورًا', 'b7cdc6b91b614b7dbb9f2907a48ee03a956195dec01065f91987c2d1c2234ece', 30, 59, 236),
  (5898, 84, 14, '84:14', 'إِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ', 'إِنَّهُ ظَنَّ أَن لَّن يَحُورَ', '2eafcbf57c5e461e68f8456b6e8af687bf72a49f9df70f262afe3a21f57a6a13', 30, 59, 236),
  (5899, 84, 15, '84:15', 'بَلَىٰٓ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرًۭا', 'بَلَىٰ إِنَّ رَبَّهُ كَانَ بِهِ بَصِيرًا', '075d220e5ea50343887b20f5cb96143a23d4df6466f1e17eedc03ff9427d01bc', 30, 59, 236),
  (5900, 84, 16, '84:16', 'فَلَآ أُقْسِمُ بِٱلشَّفَقِ', 'فَلَا أُقْسِمُ بِالشَّفَقِ', '0e2ec929f6bcf36df817035b91cc94cdc75d5e3059f0ba044f3d6e57b0ab5acf', 30, 59, 236),
  (5901, 84, 17, '84:17', 'وَٱلَّيْلِ وَمَا وَسَقَ', 'وَاللَّيْلِ وَمَا وَسَقَ', 'eb6d4a99b9715eef6a782f3834f50d5b127388438818fc7d752f6d14c3a1aa80', 30, 59, 236),
  (5902, 84, 18, '84:18', 'وَٱلْقَمَرِ إِذَا ٱتَّسَقَ', 'وَالْقَمَرِ إِذَا اتَّسَقَ', 'e51b0b5a7da908733b7d2cd534ffed55d399bdd1adcca4ff27127c322f30e9bd', 30, 59, 236),
  (5903, 84, 19, '84:19', 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍۢ', 'لَتَرْكَبُنَّ طَبَقًا عَن طَبَقٍ', '2101ca3f22fb4391d05d769bbd4181686e5c4c2e86de4a21c734d0cef4a9cd75', 30, 59, 236),
  (5904, 84, 20, '84:20', 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', 'فَمَا لَهُمْ لَا يُؤْمِنُونَ', 'd5e49da44f9c79f7edbe47c37edd2ab6873731400957ff3e695770202334485f', 30, 59, 236),
  (5905, 84, 21, '84:21', 'وَإِذَا قُرِئَ عَلَيْهِمُ ٱلْقُرْءَانُ لَا يَسْجُدُونَ ۩', 'وَإِذَا قُرِئَ عَلَيْهِمُ الْقُرْآنُ لَا يَسْجُدُونَ ۩', '4f2c10ff78f0013e797e8c8dcba50b3977bfddd834f738ee507d410239d95627', 30, 59, 236),
  (5906, 84, 22, '84:22', 'بَلِ ٱلَّذِينَ كَفَرُوا۟ يُكَذِّبُونَ', 'بَلِ الَّذِينَ كَفَرُوا يُكَذِّبُونَ', '3192955db36ff60951db3834a5792889cf8074760d289f4cc06bfa6aa334aa11', 30, 59, 236),
  (5907, 84, 23, '84:23', 'وَٱللَّهُ أَعْلَمُ بِمَا يُوعُونَ', 'وَاللَّهُ أَعْلَمُ بِمَا يُوعُونَ', '449cefc3cd0adbaeae4ba9067cecb3a2ea989b7546697c795ab6b52c76659af5', 30, 59, 236),
  (5908, 84, 24, '84:24', 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', 'فَبَشِّرْهُم بِعَذَابٍ أَلِيمٍ', '42f61e08f9022ae7e065753834e9edefc9572a9f1ebd7635f0ddafbd3a29c63c', 30, 59, 236),
  (5909, 84, 25, '84:25', 'إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍۭ', 'إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ أَجْرٌ غَيْرُ مَمْنُونٍ', 'b01528a5bcdf45c56985709bb5cdaae4553bb4cb949c5cb54ba8568df5859e26', 30, 59, 236),
