  (6010, 89, 17, '89:17', 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ ٱلْيَتِيمَ', 'كَلَّا ۖ بَل لَّا تُكْرِمُونَ الْيَتِيمَ', 'd2b7ab60c87b15be3d9969b0a6c7cff8a68084ad5125b287f663a302fdb3d8f0', 30, 60, 237),
  (6011, 89, 18, '89:18', 'وَلَا تَحَـٰٓضُّونَ عَلَىٰ طَعَامِ ٱلْمِسْكِينِ', 'وَلَا تَحَاضُّونَ عَلَىٰ طَعَامِ الْمِسْكِينِ', '29abe3d85336b0002950d80ece24c3c257888db745a7ba5a44b634e613b39c8d', 30, 60, 237),
