  (6014, 89, 21, '89:21', 'كَلَّآ إِذَا دُكَّتِ ٱلْأَرْضُ دَكًّۭا دَكًّۭا', 'كَلَّا إِذَا دُكَّتِ الْأَرْضُ دَكًّا دَكًّا', '4618a2cb3cfe051bc036ae2e319e6b9ca6624efdbacfa74dca6672821b1edfaa', 30, 60, 237),
  (6015, 89, 22, '89:22', 'وَجَآءَ رَبُّكَ وَٱلْمَلَكُ صَفًّۭا صَفًّۭا', 'وَجَاءَ رَبُّكَ وَالْمَلَكُ صَفًّا صَفًّا', '044d50290e67fee2119a7dab88f9b503f864abd1a121b5d4e537dc588022be49', 30, 60, 237),
  (6016, 89, 23, '89:23', 'وَجِا۟ىٓءَ يَوْمَئِذٍۭ بِجَهَنَّمَ ۚ يَوْمَئِذٍۢ يَتَذَكَّرُ ٱلْإِنسَـٰنُ وَأَنَّىٰ لَهُ ٱلذِّكْرَىٰ', 'وَجِيءَ يَوْمَئِذٍ بِجَهَنَّمَ ۚ يَوْمَئِذٍ يَتَذَكَّرُ الْإِنسَانُ وَأَنَّىٰ لَهُ الذِّكْرَىٰ', 'a0dde8bf83aceeb322608b252f6dd5016f6a8f90a8099d894c1c7bd0d307971f', 30, 60, 237),
  (6017, 89, 24, '89:24', 'يَقُولُ يَـٰلَيْتَنِى قَدَّمْتُ لِحَيَاتِى', 'يَقُولُ يَا لَيْتَنِي قَدَّمْتُ لِحَيَاتِي', '344496f35becfcf9c2702e8dda3220bbfd7363116c13bf2fc05acad5f709109a', 30, 60, 237),
  (6018, 89, 25, '89:25', 'فَيَوْمَئِذٍۢ لَّا يُعَذِّبُ عَذَابَهُۥٓ أَحَدٌۭ', 'فَيَوْمَئِذٍ لَّا يُعَذِّبُ عَذَابَهُ أَحَدٌ', '580a9647c5150e70ec6f1a6ea3c0de749156f655959db787bd442e37da4a7b76', 30, 60, 237),
  (6019, 89, 26, '89:26', 'وَلَا يُوثِقُ وَثَاقَهُۥٓ أَحَدٌۭ', 'وَلَا يُوثِقُ وَثَاقَهُ أَحَدٌ', '751db60e9eec415fbc9a07d9e55c37b72d6b7fe2e299ddceea7600498dde0f39', 30, 60, 237),
  (6020, 89, 27, '89:27', 'يَـٰٓأَيَّتُهَا ٱلنَّفْسُ ٱلْمُطْمَئِنَّةُ', 'يَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ', 'a61f1dd4a3d5fa839a9be6b99f6b4761aa73d0735b56ae5315da1b35d46b35f2', 30, 60, 237),
  (6021, 89, 28, '89:28', 'ٱرْجِعِىٓ إِلَىٰ رَبِّكِ رَاضِيَةًۭ مَّرْضِيَّةًۭ', 'ارْجِعِي إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً', '8b7ca688ade9688f21dc3a9a97247ff44f09ecc6ff6f9d68539e9d42cbc36e07', 30, 60, 237),
  (6022, 89, 29, '89:29', 'فَٱدْخُلِى فِى عِبَـٰدِى', 'فَادْخُلِي فِي عِبَادِي', '297a105961eb8f50d3ef3f5b6181ec808c4747ffea4e4c8a34c859b81eef1282', 30, 60, 237),
  (6023, 89, 30, '89:30', 'وَٱدْخُلِى جَنَّتِى', 'وَادْخُلِي جَنَّتِي', '8d1db6dd0f98f4c9b9b3a0a0e6f8588143cf773411b5e734e6f801b4155fb6b7', 30, 60, 237),
  (6024, 90, 1, '90:1', 'لَآ أُقْسِمُ بِهَـٰذَا ٱلْبَلَدِ', 'لَا أُقْسِمُ بِهَٰذَا الْبَلَدِ', '713cadaed6072649ed74fdbd50fc8be97858c2ca777f12a60cb177c38192c246', 30, 60, 238),
  (6025, 90, 2, '90:2', 'وَأَنتَ حِلٌّۢ بِهَـٰذَا ٱلْبَلَدِ', 'وَأَنتَ حِلٌّ بِهَٰذَا الْبَلَدِ', 'f753f2ad917a109c3dfd5fbe1a535c1ec311fcd4c32156bed2460ac0617c5f2f', 30, 60, 238),
  (6026, 90, 3, '90:3', 'وَوَالِدٍۢ وَمَا وَلَدَ', 'وَوَالِدٍ وَمَا وَلَدَ', '6ace00ddf988d58ac2e97d425f303ed022fcda7b4bbab64524b71046cab5ec5a', 30, 60, 238),
  (6027, 90, 4, '90:4', 'لَقَدْ خَلَقْنَا ٱلْإِنسَـٰنَ فِى كَبَدٍ', 'لَقَدْ خَلَقْنَا الْإِنسَانَ فِي كَبَدٍ', '23d5d4344cb79be20696030189b5bfdd7e89b74fe670976135f1ba03cff32f7f', 30, 60, 238),
  (6028, 90, 5, '90:5', 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌۭ', 'أَيَحْسَبُ أَن لَّن يَقْدِرَ عَلَيْهِ أَحَدٌ', 'c3447cb191120320012d3a3f420f21a09077eb87dd8278d83ad232277790671c', 30, 60, 238),
  (6029, 90, 6, '90:6', 'يَقُولُ أَهْلَكْتُ مَالًۭا لُّبَدًا', 'يَقُولُ أَهْلَكْتُ مَالًا لُّبَدًا', '9ab1ec2485e3d45e4f98a9743be98a6e2060195677f1c80c9d6e753cb7011e80', 30, 60, 238),
  (6030, 90, 7, '90:7', 'أَيَحْسَبُ أَن لَّمْ يَرَهُۥٓ أَحَدٌ', 'أَيَحْسَبُ أَن لَّمْ يَرَهُ أَحَدٌ', 'c48875e866ae98d826e825cc147df8319562f9d6aa331a35fbad54270af78386', 30, 60, 238),
  (6031, 90, 8, '90:8', 'أَلَمْ نَجْعَل لَّهُۥ عَيْنَيْنِ', 'أَلَمْ نَجْعَل لَّهُ عَيْنَيْنِ', '345eb244c0ac48e53595f8575243677504bc3d82388b569d171ec7a8b68d98dd', 30, 60, 238),
  (6032, 90, 9, '90:9', 'وَلِسَانًۭا وَشَفَتَيْنِ', 'وَلِسَانًا وَشَفَتَيْنِ', '513e2b9feaa17b011ba1d293975b61dfec47dc9cdf2b94b5773fb2974e16aa49', 30, 60, 238),
  (6033, 90, 10, '90:10', 'وَهَدَيْنَـٰهُ ٱلنَّجْدَيْنِ', 'وَهَدَيْنَاهُ النَّجْدَيْنِ', 'f55391c9f3704b6aab901bb1c0952de57952ba1a3d57490c10cb4929c712ce41', 30, 60, 238),
  (6034, 90, 11, '90:11', 'فَلَا ٱقْتَحَمَ ٱلْعَقَبَةَ', 'فَلَا اقْتَحَمَ الْعَقَبَةَ', 'b477665761218de747c4112c4cbe342ef53fa7752f93c6497d1eaa7732f40701', 30, 60, 238),
  (6035, 90, 12, '90:12', 'وَمَآ أَدْرَىٰكَ مَا ٱلْعَقَبَةُ', 'وَمَا أَدْرَاكَ مَا الْعَقَبَةُ', 'c2d30948edfd38c2c8ff985e8a7eb36a74050d87c7d8e4d7de7d96ec53e9445e', 30, 60, 238),
  (6036, 90, 13, '90:13', 'فَكُّ رَقَبَةٍ', 'فَكُّ رَقَبَةٍ', 'aaa08ef1f34ff7b2c90207bd22e0ba26bb0a1f1cce5a87252f3ba4fb4cb4c3bf', 30, 60, 238),
  (6037, 90, 14, '90:14', 'أَوْ إِطْعَـٰمٌۭ فِى يَوْمٍۢ ذِى مَسْغَبَةٍۢ', 'أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ', '748a2921d6a085f5a169ac1066af1f4d5844619c57055d374138eab37ec8e06b', 30, 60, 238),
  (6038, 90, 15, '90:15', 'يَتِيمًۭا ذَا مَقْرَبَةٍ', 'يَتِيمًا ذَا مَقْرَبَةٍ', '038e5b5fee48b792162a275638d2964261266170e84ef23e1f35a312a4c619c1', 30, 60, 238),
  (6039, 90, 16, '90:16', 'أَوْ مِسْكِينًۭا ذَا مَتْرَبَةٍۢ', 'أَوْ مِسْكِينًا ذَا مَتْرَبَةٍ', 'e2a2faf184defa051ab0d40b6244c74a7dd9b1c3bfbaf15bae4f6ddd00162308', 30, 60, 238),
  (6040, 90, 17, '90:17', 'ثُمَّ كَانَ مِنَ ٱلَّذِينَ ءَامَنُوا۟ وَتَوَاصَوْا۟ بِٱلصَّبْرِ وَتَوَاصَوْا۟ بِٱلْمَرْحَمَةِ', 'ثُمَّ كَانَ مِنَ الَّذِينَ آمَنُوا وَتَوَاصَوْا بِالصَّبْرِ وَتَوَاصَوْا بِالْمَرْحَمَةِ', '076ecad1d16b4374ff362e671a90c6d60d062653b6a272fadadb532e94b3f873', 30, 60, 238),
  (6041, 90, 18, '90:18', 'أُو۟لَـٰٓئِكَ أَصْحَـٰبُ ٱلْمَيْمَنَةِ', 'أُولَٰئِكَ أَصْحَابُ الْمَيْمَنَةِ', '4988eda38b7e7090df7f2eea719c5f814125bb186876c2adf6256e350b6fc552', 30, 60, 238),
  (6042, 90, 19, '90:19', 'وَٱلَّذِينَ كَفَرُوا۟ بِـَٔايَـٰتِنَا هُمْ أَصْحَـٰبُ ٱلْمَشْـَٔمَةِ', 'وَالَّذِينَ كَفَرُوا بِآيَاتِنَا هُمْ أَصْحَابُ الْمَشْأَمَةِ', '0b263492a97c625d7f82fffb0bb9d990e1dfba9032bc3601711915b24219198a', 30, 60, 238),
  (6043, 90, 20, '90:20', 'عَلَيْهِمْ نَارٌۭ مُّؤْصَدَةٌۢ', 'عَلَيْهِمْ نَارٌ مُّؤْصَدَةٌ', '82ef98bb61919ba9621a20973438f37160322fc515dea9a65968ae174a6fca82', 30, 60, 238),
  (6044, 91, 1, '91:1', 'وَٱلشَّمْسِ وَضُحَىٰهَا', 'وَالشَّمْسِ وَضُحَاهَا', 'ddd26ec7e37a990d30d244b622f4f967b3bae372495f4982999ae661594f7d68', 30, 60, 238),
  (6045, 91, 2, '91:2', 'وَٱلْقَمَرِ إِذَا تَلَىٰهَا', 'وَالْقَمَرِ إِذَا تَلَاهَا', 'd8a4c9c825fe8056d828a97eea2616cb6b69248a56798754d778c9471f28e5d3', 30, 60, 238),
  (6046, 91, 3, '91:3', 'وَٱلنَّهَارِ إِذَا جَلَّىٰهَا', 'وَالنَّهَارِ إِذَا جَلَّاهَا', 'ab9e23473b78be8672207581fd5c98a164da4a01579cb0179444f139bb4da6e9', 30, 60, 238),
  (6047, 91, 4, '91:4', 'وَٱلَّيْلِ إِذَا يَغْشَىٰهَا', 'وَاللَّيْلِ إِذَا يَغْشَاهَا', '50f79fe387f6721f00daef7ff3db0cc1632ace54577dbf51fb9c3080bdc9b791', 30, 60, 238),
  (6048, 91, 5, '91:5', 'وَٱلسَّمَآءِ وَمَا بَنَىٰهَا', 'وَالسَّمَاءِ وَمَا بَنَاهَا', '0f871da71024e756d4a79316460868a7271b478d4698af9749f56b72c4b0a99e', 30, 60, 238),
  (6049, 91, 6, '91:6', 'وَٱلْأَرْضِ وَمَا طَحَىٰهَا', 'وَالْأَرْضِ وَمَا طَحَاهَا', '9b1e248692413a6d16d40d1f3661a9d46d5afce65e7181fee599a5075a71a2ba', 30, 60, 238),
  (6050, 91, 7, '91:7', 'وَنَفْسٍۢ وَمَا سَوَّىٰهَا', 'وَنَفْسٍ وَمَا سَوَّاهَا', '782115148e07c349070a672b634aee10bcb454de985af0e54ff469f56643139e', 30, 60, 238),
  (6051, 91, 8, '91:8', 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا', 'فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَاهَا', '16306088fc3cfd6cdad6124e470bfef77bfffeb336fbf14030580acbbe5b95d3', 30, 60, 238),
  (6052, 91, 9, '91:9', 'قَدْ أَفْلَحَ مَن زَكَّىٰهَا', 'قَدْ أَفْلَحَ مَن زَكَّاهَا', '759c24980882d563bd88f0d6131818a2f7708d08d85fdf76e87d495de7edfb49', 30, 60, 238),
  (6053, 91, 10, '91:10', 'وَقَدْ خَابَ مَن دَسَّىٰهَا', 'وَقَدْ خَابَ مَن دَسَّاهَا', '6e800dee2772c4aebc653bd18301ddda26fd413208127c6e31aa3e1721e65045', 30, 60, 238),
  (6054, 91, 11, '91:11', 'كَذَّبَتْ ثَمُودُ بِطَغْوَىٰهَآ', 'كَذَّبَتْ ثَمُودُ بِطَغْوَاهَا', '8445d13e755cd2d3b14acbf612371ee15e465a969a709421f15f634afedd0150', 30, 60, 238),
  (6055, 91, 12, '91:12', 'إِذِ ٱنۢبَعَثَ أَشْقَىٰهَا', 'إِذِ انبَعَثَ أَشْقَاهَا', '9d3487e2735bfb63ba396c2549fa0ee550f9d391991edd39427b300a32e8b2df', 30, 60, 238),
  (6056, 91, 13, '91:13', 'فَقَالَ لَهُمْ رَسُولُ ٱللَّهِ نَاقَةَ ٱللَّهِ وَسُقْيَـٰهَا', 'فَقَالَ لَهُمْ رَسُولُ اللَّهِ نَاقَةَ اللَّهِ وَسُقْيَاهَا', '47bf1d2c66f85d99a9199856bc80b35642838bb7e411e97c9dc04277394d342b', 30, 60, 238),
  (6057, 91, 14, '91:14', 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنۢبِهِمْ فَسَوَّىٰهَا', 'فَكَذَّبُوهُ فَعَقَرُوهَا فَدَمْدَمَ عَلَيْهِمْ رَبُّهُم بِذَنبِهِمْ فَسَوَّاهَا', '1ea49d3f96812ab6be24a17248c33bda1070721a90a4c290009199b7a852ac22', 30, 60, 238),
  (6058, 91, 15, '91:15', 'وَلَا يَخَافُ عُقْبَـٰهَا', 'وَلَا يَخَافُ عُقْبَاهَا', 'cde10f456b10c31d2d73888d1ce538532b6c551f9e2dab8aaac5f42740be2b97', 30, 60, 238),
  (6059, 92, 1, '92:1', 'وَٱلَّيْلِ إِذَا يَغْشَىٰ', 'وَاللَّيْلِ إِذَا يَغْشَىٰ', '36d7f8d9fde402e18c9f350eb050fd2468b5d3b8d5f0fc7f59ce9fda7f1f7f97', 30, 60, 238),
  (6060, 92, 2, '92:2', 'وَٱلنَّهَارِ إِذَا تَجَلَّىٰ', 'وَالنَّهَارِ إِذَا تَجَلَّىٰ', 'da3886c507434eec91e73524db610bb3d64c51398ad596a2b273f6737777af98', 30, 60, 238),
  (6061, 92, 3, '92:3', 'وَمَا خَلَقَ ٱلذَّكَرَ وَٱلْأُنثَىٰٓ', 'وَمَا خَلَقَ الذَّكَرَ وَالْأُنثَىٰ', 'f83624642fac786b2ae5b44a94f570165dd3f6948ab580910f65e2e685656458', 30, 60, 238),
  (6062, 92, 4, '92:4', 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', 'إِنَّ سَعْيَكُمْ لَشَتَّىٰ', '2285b238b5d82dc2660a5a833bc28af188762c46aa67eb2ab1ee6c5abc66d6a4', 30, 60, 238),
  (6063, 92, 5, '92:5', 'فَأَمَّا مَنْ أَعْطَىٰ وَٱتَّقَىٰ', 'فَأَمَّا مَنْ أَعْطَىٰ وَاتَّقَىٰ', 'b96ce9e113f5709c323ad57d4f51c1feb19e554e3516c0d16580330241d40075', 30, 60, 238),
  (6064, 92, 6, '92:6', 'وَصَدَّقَ بِٱلْحُسْنَىٰ', 'وَصَدَّقَ بِالْحُسْنَىٰ', '9f01cdf90db8f1de3c5c8b20a596991307192c81fdd881bada6a4b04984cf2e1', 30, 60, 238),
  (6065, 92, 7, '92:7', 'فَسَنُيَسِّرُهُۥ لِلْيُسْرَىٰ', 'فَسَنُيَسِّرُهُ لِلْيُسْرَىٰ', '358fc5e2f353b01d7dae6fb36f79406e84aed697d089e85001bf162dbe12f92b', 30, 60, 238)
INSERT INTO ayahs (id, surah_id, verse_number, verse_key, text_uthmani, text_imlaei, text_uthmani_sha256, juz_number, hizb_number, rub_el_hizb_number) VALUES
  (6066, 92, 8, '92:8', 'وَأَمَّا مَنۢ بَخِلَ وَٱسْتَغْنَىٰ', 'وَأَمَّا مَن بَخِلَ وَاسْتَغْنَىٰ', 'ad8198af45715d23d9a04b6cef76935cb7b92f723f35403b6ff6767dd97ce595', 30, 60, 238),
