  (6125, 96, 19, '96:19', 'كَلَّا لَا تُطِعْهُ وَٱسْجُدْ وَٱقْتَرِب ۩', 'كَلَّا لَا تُطِعْهُ وَاسْجُدْ وَاقْتَرِب ۩', 'af5351eb422582e1e65daf7efacc88ec50791956b5b8f9471bd7d4f2e2aea6ae', 30, 60, 239),
  (6126, 97, 1, '97:1', 'إِنَّآ أَنزَلْنَـٰهُ فِى لَيْلَةِ ٱلْقَدْرِ', 'إِنَّا أَنزَلْنَاهُ فِي لَيْلَةِ الْقَدْرِ', '9d668a0a56c55cf263b8a2b82367461e9cb774454ad2bc9aa7d31f9314e69b8a', 30, 60, 239),
  (6127, 97, 2, '97:2', 'وَمَآ أَدْرَىٰكَ مَا لَيْلَةُ ٱلْقَدْرِ', 'وَمَا أَدْرَاكَ مَا لَيْلَةُ الْقَدْرِ', 'b733d7c19ede87734e9223ced2e7f23977bd9e975b5a8110f4c1ee3cd0c576ad', 30, 60, 239),
  (6128, 97, 3, '97:3', 'لَيْلَةُ ٱلْقَدْرِ خَيْرٌۭ مِّنْ أَلْفِ شَهْرٍۢ', 'لَيْلَةُ الْقَدْرِ خَيْرٌ مِّنْ أَلْفِ شَهْرٍ', '149b004b468ff6a3604ccd1f68b2655baa336d2808ffc1f1644e6ef3a89dbd06', 30, 60, 239),
  (6129, 97, 4, '97:4', 'تَنَزَّلُ ٱلْمَلَـٰٓئِكَةُ وَٱلرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍۢ', 'تَنَزَّلُ الْمَلَائِكَةُ وَالرُّوحُ فِيهَا بِإِذْنِ رَبِّهِم مِّن كُلِّ أَمْرٍ', '144e1d25fa5d589d2c466a3068adc5efb8586e910394f60a4795f374578cb545', 30, 60, 239),
  (6130, 97, 5, '97:5', 'سَلَـٰمٌ هِىَ حَتَّىٰ مَطْلَعِ ٱلْفَجْرِ', 'سَلَامٌ هِيَ حَتَّىٰ مَطْلَعِ الْفَجْرِ', '206d00c6f94e240811b0f732d53d013e6ad9671e9f79c381358a62de107ff517', 30, 60, 239),
  (6131, 98, 1, '98:1', 'لَمْ يَكُنِ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ ٱلْبَيِّنَةُ', 'لَمْ يَكُنِ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأْتِيَهُمُ الْبَيِّنَةُ', '75c8462afacc0020af926137b72f31fb0c09c2254731da1bf07c467a94949d32', 30, 60, 239),
  (6132, 98, 2, '98:2', 'رَسُولٌۭ مِّنَ ٱللَّهِ يَتْلُوا۟ صُحُفًۭا مُّطَهَّرَةًۭ', 'رَسُولٌ مِّنَ اللَّهِ يَتْلُو صُحُفًا مُّطَهَّرَةً', '46e4f4dba7f30acb2255d264c0f30172c560ddebcdd042de0698e46c130603ae', 30, 60, 239),
  (6133, 98, 3, '98:3', 'فِيهَا كُتُبٌۭ قَيِّمَةٌۭ', 'فِيهَا كُتُبٌ قَيِّمَةٌ', '6c38fe8de83fb1e80a4f83484f66ca3c2e8805fd38c0c89148dd26e474b9ac46', 30, 60, 239),
  (6134, 98, 4, '98:4', 'وَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَتْهُمُ ٱلْبَيِّنَةُ', 'وَمَا تَفَرَّقَ الَّذِينَ أُوتُوا الْكِتَابَ إِلَّا مِن بَعْدِ مَا جَاءَتْهُمُ الْبَيِّنَةُ', 'eb15fb6459062d056abc2562010f7a9b9924f028ce89813a8d483a62baf98cf5', 30, 60, 239),
  (6135, 98, 5, '98:5', 'وَمَآ أُمِرُوٓا۟ إِلَّا لِيَعْبُدُوا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُوا۟ ٱلصَّلَوٰةَ وَيُؤْتُوا۟ ٱلزَّكَوٰةَ ۚ وَذَٰلِكَ دِينُ ٱلْقَيِّمَةِ', 'وَمَا أُمِرُوا إِلَّا لِيَعْبُدُوا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ حُنَفَاءَ وَيُقِيمُوا الصَّلَاةَ وَيُؤْتُوا الزَّكَاةَ ۚ وَذَٰلِكَ دِينُ الْقَيِّمَةِ', 'b05bf29990fe0f6849746332eae0caacd090e7226fc9fa23ad9e3584f479f971', 30, 60, 239),
  (6136, 98, 6, '98:6', 'إِنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْ أَهْلِ ٱلْكِتَـٰبِ وَٱلْمُشْرِكِينَ فِى نَارِ جَهَنَّمَ خَـٰلِدِينَ فِيهَآ ۚ أُو۟لَـٰٓئِكَ هُمْ شَرُّ ٱلْبَرِيَّةِ', 'إِنَّ الَّذِينَ كَفَرُوا مِنْ أَهْلِ الْكِتَابِ وَالْمُشْرِكِينَ فِي نَارِ جَهَنَّمَ خَالِدِينَ فِيهَا ۚ أُولَٰئِكَ هُمْ شَرُّ الْبَرِيَّةِ', '8891e8f3c7f967e61fda18a806a2b8ca158f90c117276a9af4e83dda255ebc53', 30, 60, 239),
  (6137, 98, 7, '98:7', 'إِنَّ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ أُو۟لَـٰٓئِكَ هُمْ خَيْرُ ٱلْبَرِيَّةِ', 'إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ أُولَٰئِكَ هُمْ خَيْرُ الْبَرِيَّةِ', '0d25f4a2fe07a380a4bba9fd7fddaf56ab81cfe5266f76d0642cc702c651c390', 30, 60, 239),
  (6138, 98, 8, '98:8', 'جَزَآؤُهُمْ عِندَ رَبِّهِمْ جَنَّـٰتُ عَدْنٍۢ تَجْرِى مِن تَحْتِهَا ٱلْأَنْهَـٰرُ خَـٰلِدِينَ فِيهَآ أَبَدًۭا ۖ رَّضِىَ ٱللَّهُ عَنْهُمْ وَرَضُوا۟ عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِىَ رَبَّهُۥ', 'جَزَاؤُهُمْ عِندَ رَبِّهِمْ جَنَّاتُ عَدْنٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ خَالِدِينَ فِيهَا أَبَدًا ۖ رَّضِيَ اللَّهُ عَنْهُمْ وَرَضُوا عَنْهُ ۚ ذَٰلِكَ لِمَنْ خَشِيَ رَبَّهُ', 'e236ca83a73883b4917fca4ae27bb6912e7e4cd30c76c227fb5ab19378650acd', 30, 60, 239),
  (6139, 99, 1, '99:1', 'إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا', 'إِذَا زُلْزِلَتِ الْأَرْضُ زِلْزَالَهَا', 'c4830f1f06719f33daa78f909236e0ffe6698f391b00ba0453a80499d31d69bc', 30, 60, 239),
  (6140, 99, 2, '99:2', 'وَأَخْرَجَتِ ٱلْأَرْضُ أَثْقَالَهَا', 'وَأَخْرَجَتِ الْأَرْضُ أَثْقَالَهَا', '8a049d5ea7457d5c32afc707a91a3456bb2f543faaedb11b3dbee7f79893a128', 30, 60, 239),
  (6141, 99, 3, '99:3', 'وَقَالَ ٱلْإِنسَـٰنُ مَا لَهَا', 'وَقَالَ الْإِنسَانُ مَا لَهَا', 'b25ac0ebc21beedb0280e933e78c44a43ae1fb10ee54080e4b8c64fcab7dd85c', 30, 60, 239),
  (6142, 99, 4, '99:4', 'يَوْمَئِذٍۢ تُحَدِّثُ أَخْبَارَهَا', 'يَوْمَئِذٍ تُحَدِّثُ أَخْبَارَهَا', 'dd5c0b06aa38fc8e6b6961d14a2a72a7cec4966258d8e00d9d717aa26d64b8ff', 30, 60, 239),
  (6143, 99, 5, '99:5', 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', 'بِأَنَّ رَبَّكَ أَوْحَىٰ لَهَا', '00c4e425bfb140e7ace00d401e05e26d0bac90e559f55fe2c61f0c0422ec0c17', 30, 60, 239),
  (6144, 99, 6, '99:6', 'يَوْمَئِذٍۢ يَصْدُرُ ٱلنَّاسُ أَشْتَاتًۭا لِّيُرَوْا۟ أَعْمَـٰلَهُمْ', 'يَوْمَئِذٍ يَصْدُرُ النَّاسُ أَشْتَاتًا لِّيُرَوْا أَعْمَالَهُمْ', '9edd815b29a7e6301b7248f767a7a72c8599eab7af9928d31da5238847a84aa3', 30, 60, 239),
  (6145, 99, 7, '99:7', 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًۭا يَرَهُۥ', 'فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُ', '68f4abc2a831d985211188458ac9e8e0d13f7aa05e2194a69eb6692867affde6', 30, 60, 239),
  (6146, 99, 8, '99:8', 'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍۢ شَرًّۭا يَرَهُۥ', 'وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُ', '8df86ff8cf6e6d1009e34299ba9d6f4f1766d74ec3d6decca3f6d693b1a905f5', 30, 60, 239),
  (6147, 100, 1, '100:1', 'وَٱلْعَـٰدِيَـٰتِ ضَبْحًۭا', 'وَالْعَادِيَاتِ ضَبْحًا', '71b4796d7ae0119a920f2ac5eccf021d03930c3a4d9e8de4663fe7b4b6630d39', 30, 60, 239),
  (6148, 100, 2, '100:2', 'فَٱلْمُورِيَـٰتِ قَدْحًۭا', 'فَالْمُورِيَاتِ قَدْحًا', 'bc3a5fd4a2709c0336f2345a38b63e59ac9d434f2297d0f148b32357f41b9709', 30, 60, 239),
  (6149, 100, 3, '100:3', 'فَٱلْمُغِيرَٰتِ صُبْحًۭا', 'فَالْمُغِيرَاتِ صُبْحًا', 'a6101bf858bd60ce8dc83f62dd11d64b508a266d82ba93e3a26a17d0d3d8894b', 30, 60, 239),
  (6150, 100, 4, '100:4', 'فَأَثَرْنَ بِهِۦ نَقْعًۭا', 'فَأَثَرْنَ بِهِ نَقْعًا', '4ca63567ff7c36113c77d52b43cc869a3c414c60f0551b364c618b21d45c89ad', 30, 60, 239),
  (6151, 100, 5, '100:5', 'فَوَسَطْنَ بِهِۦ جَمْعًا', 'فَوَسَطْنَ بِهِ جَمْعًا', '5931318a3ca13407d43aec10c33cb7a4ac949dbaf38028fea66a839566d40638', 30, 60, 239),
  (6152, 100, 6, '100:6', 'إِنَّ ٱلْإِنسَـٰنَ لِرَبِّهِۦ لَكَنُودٌۭ', 'إِنَّ الْإِنسَانَ لِرَبِّهِ لَكَنُودٌ', '35814ddf0bb2f1be506214c9a545e2c4b77477812d3fbea0b4cdba21298e1b0f', 30, 60, 239),
  (6153, 100, 7, '100:7', 'وَإِنَّهُۥ عَلَىٰ ذَٰلِكَ لَشَهِيدٌۭ', 'وَإِنَّهُ عَلَىٰ ذَٰلِكَ لَشَهِيدٌ', '2eabc6fcac937fc6059cc59a2f0a45b5dc6f652d2c793c6224e17aca055a1acb', 30, 60, 239),
  (6154, 100, 8, '100:8', 'وَإِنَّهُۥ لِحُبِّ ٱلْخَيْرِ لَشَدِيدٌ', 'وَإِنَّهُ لِحُبِّ الْخَيْرِ لَشَدِيدٌ', '7ac23a7192810b9b11eb3b01af1077bddbcd4233f2c6b303e0a9d275eaf966f9', 30, 60, 239),
  (6155, 100, 9, '100:9', '۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِى ٱلْقُبُورِ', '۞ أَفَلَا يَعْلَمُ إِذَا بُعْثِرَ مَا فِي الْقُبُورِ', 'da4bd486aceff31ae9cff8ac0095523f2882f5c2072beef9663f78951bda7eda', 30, 60, 240),
  (6156, 100, 10, '100:10', 'وَحُصِّلَ مَا فِى ٱلصُّدُورِ', 'وَحُصِّلَ مَا فِي الصُّدُورِ', 'aeff019f4247fc1966069a8946f9ea3249c90979ea3d98abd6105e78f6c57f3c', 30, 60, 240),
  (6157, 100, 11, '100:11', 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍۢ لَّخَبِيرٌۢ', 'إِنَّ رَبَّهُم بِهِمْ يَوْمَئِذٍ لَّخَبِيرٌ', '11fce36991f2843904a9881763e9bcece63dd1c26e74143285934bf140de6c26', 30, 60, 240),
  (6158, 101, 1, '101:1', 'ٱلْقَارِعَةُ', 'الْقَارِعَةُ', '8b8a47929f71fdb8bd13127479cb4845495aa5f801c75cfeb17eed6d42736435', 30, 60, 240),
  (6159, 101, 2, '101:2', 'مَا ٱلْقَارِعَةُ', 'مَا الْقَارِعَةُ', '14130c715ca171c924ab38f83bae2cb7d367cae40016482f0dd9d5f65c229fec', 30, 60, 240),
  (6160, 101, 3, '101:3', 'وَمَآ أَدْرَىٰكَ مَا ٱلْقَارِعَةُ', 'وَمَا أَدْرَاكَ مَا الْقَارِعَةُ', '3b028e27a114ddd1c4834ca58c7891c017526e985a721ff7713daa75dbd16dee', 30, 60, 240),
  (6161, 101, 4, '101:4', 'يَوْمَ يَكُونُ ٱلنَّاسُ كَٱلْفَرَاشِ ٱلْمَبْثُوثِ', 'يَوْمَ يَكُونُ النَّاسُ كَالْفَرَاشِ الْمَبْثُوثِ', '74b5ba8fe304606d6556d3263c4663e624608a01cece3a19c8358487bc196a81', 30, 60, 240),
  (6162, 101, 5, '101:5', 'وَتَكُونُ ٱلْجِبَالُ كَٱلْعِهْنِ ٱلْمَنفُوشِ', 'وَتَكُونُ الْجِبَالُ كَالْعِهْنِ الْمَنفُوشِ', '0787db3b2384d84f09e2f0d37bb80fa4350373d2aafe6361de3704223e924637', 30, 60, 240),
  (6163, 101, 6, '101:6', 'فَأَمَّا مَن ثَقُلَتْ مَوَٰزِينُهُۥ', 'فَأَمَّا مَن ثَقُلَتْ مَوَازِينُهُ', '46afc91e7c7ca40ad61749c00e2bcaccde439280517c1fcec65499e5d7d0550c', 30, 60, 240),
  (6164, 101, 7, '101:7', 'فَهُوَ فِى عِيشَةٍۢ رَّاضِيَةٍۢ', 'فَهُوَ فِي عِيشَةٍ رَّاضِيَةٍ', '903cadc3d6a9d2db9ac15a3cd76b4a36d14798f46fb75a73c56f73c521c0b68e', 30, 60, 240),
  (6165, 101, 8, '101:8', 'وَأَمَّا مَنْ خَفَّتْ مَوَٰزِينُهُۥ', 'وَأَمَّا مَنْ خَفَّتْ مَوَازِينُهُ', '3fc837b52094d0b7935e6cc7bea31aa2eff1a27d4e8830dbf19d1e4932df30d9', 30, 60, 240)
INSERT INTO ayahs (id, surah_id, verse_number, verse_key, text_uthmani, text_imlaei, text_uthmani_sha256, juz_number, hizb_number, rub_el_hizb_number) VALUES
