  (6221, 111, 5, '111:5', 'فِى جِيدِهَا حَبْلٌۭ مِّن مَّسَدٍۭ', 'فِي جِيدِهَا حَبْلٌ مِّن مَّسَدٍ', '828eca856d16c0f00fcca9d798dff3e0babdf90539be2aca13efe982a1ef0dd6', 30, 60, 240),
  (6222, 112, 1, '112:1', 'قُلْ هُوَ ٱللَّهُ أَحَدٌ', 'قُلْ هُوَ اللَّهُ أَحَدٌ', '5479eee85e42dd3315cb339a95115328f2617f0d23214c832cc38f519d6ccd35', 30, 60, 240),
  (6223, 112, 2, '112:2', 'ٱللَّهُ ٱلصَّمَدُ', 'اللَّهُ الصَّمَدُ', 'a30b680c0f56ff9a29c1384eac94f728f9cfd0e8f1d3798a2e4916d91e57f57e', 30, 60, 240),
  (6224, 112, 3, '112:3', 'لَمْ يَلِدْ وَلَمْ يُولَدْ', 'لَمْ يَلِدْ وَلَمْ يُولَدْ', 'fe38e7c9006a6b6032988cba2fbf80978274b83513edc6338bd33cdf8cda5e30', 30, 60, 240),
  (6225, 112, 4, '112:4', 'وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ', 'وَلَمْ يَكُن لَّهُ كُفُوًا أَحَدٌ', '501757e7e551d18bc11deafa6e6fc4e5290fc31931b59ac5d12d89716efe273d', 30, 60, 240),
  (6226, 113, 1, '113:1', 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ', 'قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ', '956b86b784e1ca1be40214d7ec88ee1a92e0ab79c91f1878f5c1c6412cae854c', 30, 60, 240),
  (6227, 113, 2, '113:2', 'مِن شَرِّ مَا خَلَقَ', 'مِن شَرِّ مَا خَلَقَ', 'e20c1399e94c41de16f60f608354faed7eed0a2fb0e9e5b934979b1cfa963190', 30, 60, 240),
  (6228, 113, 3, '113:3', 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ', 'b3501f9b1a17ac364b30a1e43e18f08c874a06bf01fb355061b6dec1da750a7b', 30, 60, 240),
  (6229, 113, 4, '113:4', 'وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ', 'وَمِن شَرِّ النَّفَّاثَاتِ فِي الْعُقَدِ', 'ef38f895ee34750c33169bfa4f3c880e719300d070789d362e73e9890b3e1e8f', 30, 60, 240),
  (6230, 113, 5, '113:5', 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ', '2a974f26ea539b4ce14e2d0d8e9b3d63768255658a5cfcfb2cbfeb74117f4daa', 30, 60, 240),
  (6231, 114, 1, '114:1', 'قُلْ أَعُوذُ بِرَبِّ ٱلنَّاسِ', 'قُلْ أَعُوذُ بِرَبِّ النَّاسِ', '25f9b2e45068f55fca746c4629406d83837c55fdd3b3dd0061446867bb5e1df4', 30, 60, 240),
  (6232, 114, 2, '114:2', 'مَلِكِ ٱلنَّاسِ', 'مَلِكِ النَّاسِ', 'ee43221a2d70da314a28481e2858b355b84ea76cc5505a17b6d6d8f592ce3dce', 30, 60, 240),
  (6233, 114, 3, '114:3', 'إِلَـٰهِ ٱلنَّاسِ', 'إِلَٰهِ النَّاسِ', '701a2453af8b30a59407ad87b7dd98088145b9048e7bb75d13f6cc0607199355', 30, 60, 240),
  (6234, 114, 4, '114:4', 'مِن شَرِّ ٱلْوَسْوَاسِ ٱلْخَنَّاسِ', 'مِن شَرِّ الْوَسْوَاسِ الْخَنَّاسِ', 'cdb6f393a56ccaa9a72aae865781f619f99768ac74efb2931761b968a3d60d82', 30, 60, 240),
  (6235, 114, 5, '114:5', 'ٱلَّذِى يُوَسْوِسُ فِى صُدُورِ ٱلنَّاسِ', 'الَّذِي يُوَسْوِسُ فِي صُدُورِ النَّاسِ', 'f8578dc798a33711fa495cb49159b90a9267111f19f5aaa3189c3c184bcd14dd', 30, 60, 240),
