INSERT INTO verse_translations (ayah_id, resource_id, translator_name, language_code, text, source_attribution) VALUES
  (1, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'Rahman ve Rahim olan Allah''ın adıyla:', 'Quran.com API v4'),
  (1, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'Rahmân ve Rahîm olan Allah''ın ismiyle.', 'Quran.com API v4'),
  (2, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'Hamd, Alemlerin Rabbi Allah''a mahsustur.', 'Quran.com API v4'),
  (2, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'Hamd o âlemlerin Rabbi,', 'Quran.com API v4'),
  (3, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'O Rahman ve Rahim''dir,', 'Quran.com API v4'),
  (3, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'O Rahmân ve Rahim,', 'Quran.com API v4'),
  (4, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'Din Gününün sahibidir.', 'Quran.com API v4'),
  (4, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'O, din gününün maliki Allah''ın.', 'Quran.com API v4'),
  (5, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'Ancak Sana kulluk eder ve yalnız Senden yardım dileriz.', 'Quran.com API v4'),
  (5, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'Ancak sana ederiz kulluğu, ibadeti ve ancak senden dileriz yardımı, inayeti. (Ya Rab!).', 'Quran.com API v4'),
  (6, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'Bizi doğru yola eriştir.', 'Quran.com API v4'),
  (6, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'Hidayet eyle bizi doğru yola,', 'Quran.com API v4'),
  (7, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'Nimete erdirdiğin kimselerin yoluna; gazaba uğrayanların, ya da sapıtanların yoluna değil.', 'Quran.com API v4'),
  (7, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'O kendilerine nimet verdiğin mutlu kimselerin yoluna; o gazaba uğramışların ve o sapmışların yoluna değil.', 'Quran.com API v4'),
  (5673, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'Neyi soruşturuyorlar?', 'Quran.com API v4'),
  (5673, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'Birbirlerine neyi soruyorlar?', 'Quran.com API v4'),
