  (5783, 77, 'Diyanet İşleri Başkanlığı', 'tr', 'Doğrusu suyu bol bol indirmekteyiz.', 'Quran.com API v4'),
  (5783, 52, 'Elmalılı Muhammed Hamdi Yazır', 'tr', 'Biz o suyu bol bol döktük.', 'Quran.com API v4'),
